<?php require 'functions.php';$cart=$_SESSION['cart']??[];if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['remove']))unset($_SESSION['cart'][(int)$_POST['remove']]);if(isset($_POST['update']))foreach($_POST['qty'] as $id=>$qty){$qty=max(0,(int)$qty);if($qty===0)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=$qty;}go('cart.php');}$items=[];$total=0;foreach($cart as $id=>$qty){$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([$id]);if($p=$s->fetch()){$p['qty']=$qty;$p['subtotal']=$qty*$p['price'];$items[]=$p;$total+=$p['subtotal'];}}$pageTitle='Keranjang';require 'header.php';?><section class="section"><h2>Keranjang belanja</h2><?php if(!$items):?><p>Keranjang masih kosong. <a href="<?=url('index.php')?>">Mulai belanja</a></p><?php else:?><form method="post"><?=csrf_field()?><div class="cart-list"><?php foreach($items as $p):?><div class="cart-item"><img src="<?=e(image_url($p['image']))?>"><div><b><?=e($p['name'])?></b><p><?=rupiah($p['price'])?></p><input type="number" name="qty[<?=$p['id']?>]" value="<?=$p['qty']?>" min="0" max="<?=$p['stock']?>"></div><strong><?=rupiah($p['subtotal'])?></strong><button name="remove" value="<?=$p['id']?>" class="remove">Hapus</button></div><?php endforeach;?></div><button class="btn secondary" name="update">Perbarui Keranjang</button></form><div class="total"><h3>Total: <?=rupiah($total)?></h3><a class="btn" href="<?=url('checkout.php')?>">Lanjut Checkout</a></div><?php endif;?></section><?php require 'footer.php';?>